extern void password_box_event_actions(lv_event_t * e);

void password_box_key_event(uint32_t key,lv_obj_t * ui_ScreenPassword)
{
    password_box_screen_obj_t * p_screen_param = lv_obj_get_user_data(ui_ScreenPassword);
    char *          password;
    uint32_t        count;

    switch (key)
    {
        case LV_KEY_UP:
        case LV_KEY_DOWN:
            break;

        case LV_KEY_ESC:
            lv_indev_wait_release(lv_indev_get_act());
            lv_group_focus_obj(p_screen_param->enter_param.parent);

            if (p_screen_param->enter_param.fun_password_callbakc_cancel)
                p_screen_param->enter_param.fun_password_callbakc_cancel(p_screen_param->enter_param.user_data);

            if (p_screen_param) {
                lv_obj_set_user_data(ui_ScreenPassword,NULL);
                lv_mem_free(p_screen_param);

                }

            lv_obj_remove_event_cb(ui_ScreenPassword,password_box_event_actions);

            //lv_obj_del_delayed_custom(ui_ScreenPassword,100);
            lv_obj_del(ui_ScreenPassword);
            break;

        case LV_KEY_ENTER:
            lv_indev_wait_release(lv_indev_get_act());
            password = (char *) lv_textarea_get_text(p_screen_param->textarea);

            if (password == NULL)
                break;

            count = strlen(password);

            if (count < 4)
                break;

            lv_group_focus_obj(p_screen_param->enter_param.parent);

            if (p_screen_param->enter_param.fun_password_callback_ok)
                p_screen_param->enter_param.fun_password_callback_ok(p_screen_param->enter_param.user_data,password);

            if (p_screen_param) {
                lv_obj_set_user_data(ui_ScreenPassword,NULL);
                lv_mem_free(p_screen_param);

                }

            lv_obj_remove_event_cb(ui_ScreenPassword,password_box_event_actions);

            //lv_obj_del_delayed_custom(ui_ScreenPassword,100);
            lv_obj_del(ui_ScreenPassword);
            break;

        case LV_KEY_DEL:
            {
                lv_textarea_del_char(p_screen_param->textarea);
                password            = (char *) lv_textarea_get_text(p_screen_param->textarea);

                if (password == NULL) {
                    lv_obj_set_style_text_opa(p_screen_param->label_del,LV_OPA_40,LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_opa(p_screen_param->label_ok,LV_OPA_40,LV_PART_MAIN | LV_STATE_DEFAULT);
                    break;
                    }

                count               = strlen(password);

                if (count == 0)
                    lv_obj_set_style_text_opa(p_screen_param->label_del,LV_OPA_40,LV_PART_MAIN | LV_STATE_DEFAULT);

                if (count < 4)
                    lv_obj_set_style_text_opa(p_screen_param->label_ok,LV_OPA_40,LV_PART_MAIN | LV_STATE_DEFAULT);
                }
            break;

        case LV_KEY_END:
            break;

        case LV_KEY_9:
        case LV_KEY_8:
        case LV_KEY_7:
        case LV_KEY_6:
        case LV_KEY_5:
        case LV_KEY_4:
        case LV_KEY_3:
        case LV_KEY_2:
        case LV_KEY_1:
        case LV_KEY_0:
            {
                uint32_t        c;

                if ((key >= LV_KEY_0) && (key <= LV_KEY_9)) {
                    c                   = '0' + key - LV_KEY_0;
                    lv_textarea_add_char(p_screen_param->textarea,c);
                    }

                password            = (char *) lv_textarea_get_text(p_screen_param->textarea);

                if (password == NULL)
                    break;

                count               = strlen(password);

                if (count > 0)
                    lv_obj_set_style_text_opa(p_screen_param->label_del,LV_OPA_100,LV_PART_MAIN | LV_STATE_DEFAULT);

                if (count >= 4)
                    lv_obj_set_style_text_opa(p_screen_param->label_ok,LV_OPA_100,LV_PART_MAIN | LV_STATE_DEFAULT);

                }
            break;
        }

}



void password_box_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    password_box_key_event(key,obj);
                    }
                }
            break;

        case LV_EVENT_DEFOCUSED:
        case LV_EVENT_FOCUSED:
            //screen_sim_pin_focus_event(event_code,e->user_data);
            break;

        case LV_EVENT_DELETE:
            {
                password_box_screen_obj_t * p_screen_param;
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    p_screen_param      = lv_obj_get_user_data(obj);

                    if (p_screen_param) {
                        lv_obj_set_user_data(e->user_data,NULL);
                        lv_mem_free(p_screen_param);

                        //__inf("LV_EVENT_DELETE1");
                        }
                    }

                //__inf("LV_EVENT_DELETE2");
                }
            break;

        default:
            break;
        }


}



